from decimal import Decimal

import pytest
from hypothesis import given
from hypothesis import strategies as st

from refproj.pricing import format_price, parse_price

# I1's domain: every price from 0.00 to 9,999,999.99 in whole cents. The contract's own
# examples spell prices both ways (`Decimal("12.50")`, `Decimal("12.5")`, `Decimal("0")`),
# so each price is drawn in either spelling.
_CENTS = st.decimals(min_value=Decimal("0.00"), max_value=Decimal("9999999.99"), places=2)
PRICES = _CENTS | _CENTS.map(lambda price: price.normalize())


def test_format_always_prints_two_decimals() -> None:
    assert format_price(Decimal("12.5")) == "12.50"


def test_format_groups_thousands_with_commas() -> None:
    assert format_price(Decimal("1234.5")) == "1,234.50"


