from decimal import Decimal

import pytest
from hypothesis import given
from hypothesis import strategies as st

from refproj.pricing import format_price, parse_price

# Every price from 0.00 to 9,999,999.99 in whole cents, written both with two decimals
# (`12.50`) and in its shortest form (`12.5`, `0`): the contract calls both a price.
def _price(cents: int, shortest: bool) -> Decimal:
    price = Decimal(cents).scaleb(-2)
    return price.normalize() if shortest else price


PRICES = st.builds(_price, st.integers(min_value=0, max_value=999_999_999), st.booleans())


def test_format_always_prints_two_decimals() -> None:
    assert format_price(Decimal("12.5")) == "12.50"


def test_format_groups_thousands_with_commas() -> None:
    assert format_price(Decimal("1234.5")) == "1,234.50"


def test_format_of_zero_is_zero_point_zero_zero() -> None:
    assert format_price(Decimal("0")) == "0.00"


def test_format_prints_the_highest_price() -> None:
    assert format_price(Decimal("9999999.99")) == "9,999,999.99"


def test_format_rejects_a_price_above_the_range() -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(Decimal("10000000.00"))


def test_format_rejects_a_price_below_the_range() -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(Decimal("-0.01"))


def test_format_rejects_a_fraction_of_a_cent() -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(Decimal("12.345"))


def test_parse_reads_a_printed_price_in_cents() -> None:
    # Seam 1: compared as text, so a result that prints as `1234.5` does not pass.
    assert str(parse_price("1,234.50")) == "1234.50"


def test_parse_reads_a_price_with_the_commas_left_out() -> None:
    assert str(parse_price("1234.50")) == "1234.50"


def test_parse_reads_the_lowest_and_the_highest_printed_price() -> None:
    assert str(parse_price("0.00")) == "0.00"
    assert str(parse_price("9,999,999.99")) == "9999999.99"


@pytest.mark.parametrize(
    "text",
    ["12.5", "12", "1,23.00", "", "abc"],
    ids=["one-decimal", "no-decimals", "misplaced-comma", "empty", "letters"],
)
def test_parse_rejects_any_other_text(text: str) -> None:
    with pytest.raises(ValueError, match="not a price"):
        parse_price(text)


def test_parse_rejects_a_text_above_the_range() -> None:
    with pytest.raises(ValueError, match="not a price"):
        parse_price("10,000,000.00")


@given(PRICES)
def test_I1_a_printed_price_reads_back_as_the_same_price(price: Decimal) -> None:
    assert parse_price(format_price(price)) == price

from decimal import Decimal

import pytest
from hypothesis import given
from hypothesis import strategies as st

from refproj.pricing import format_price, parse_price

# I1's domain: every whole number of cents from 0.00 to 9,999,999.99, in each spelling a
# Decimal of that value can have (the contract itself formats Decimal("12.5") and Decimal("0")).
_SPELLINGS = (
    lambda cents: Decimal(cents).scaleb(-2),  # 12.50
    lambda cents: Decimal(cents).scaleb(-2).normalize(),  # 12.5, 0, 1E+3
    lambda cents: Decimal(cents * 10).scaleb(-3),  # 12.500
)
PRICES = st.builds(
    lambda cents, spell: spell(cents),
    st.integers(min_value=0, max_value=999_999_999),
    st.sampled_from(_SPELLINGS),
)


def test_format_always_prints_two_decimals() -> None:
    assert format_price(Decimal("12.5")) == "12.50"


def test_format_groups_thousands_with_commas() -> None:
    assert format_price(Decimal("1234.5")) == "1,234.50"


def test_format_of_zero_is_the_lower_bound() -> None:
    assert format_price(Decimal("0")) == "0.00"


def test_format_of_max_price_is_the_upper_bound() -> None:
    assert format_price(Decimal("9999999.99")) == "9,999,999.99"


def test_format_rejects_a_price_above_the_range() -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(Decimal("10000000.00"))


def test_format_rejects_a_price_below_the_range() -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(Decimal("-0.01"))


def test_format_rejects_a_fraction_of_a_cent_instead_of_rounding() -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(Decimal("12.345"))


def test_parse_reads_a_grouped_price_in_cents() -> None:
    price = parse_price("1,234.50")
    assert isinstance(price, Decimal)
    assert str(price) == "1234.50"


def test_parse_reads_a_price_with_the_commas_left_out_in_cents() -> None:
    price = parse_price("1234.50")
    assert isinstance(price, Decimal)
    assert str(price) == "1234.50"


def test_parse_reads_the_bounds_of_the_range_in_cents() -> None:
    assert str(parse_price("0.00")) == "0.00"
    assert str(parse_price("9,999,999.99")) == "9999999.99"


@pytest.mark.parametrize("text", ["12.5", "12", "1,23.00", "", "abc"])
def test_parse_rejects_text_that_is_not_a_printed_price(text: str) -> None:
    with pytest.raises(ValueError, match="not a price"):
        parse_price(text)


@pytest.mark.parametrize("text", ["$12.50", "1.234,50", "1 234.50"])
def test_parse_rejects_a_currency_sign_and_other_separators(text: str) -> None:
    with pytest.raises(ValueError, match="not a price"):
        parse_price(text)


@pytest.mark.parametrize("text", ["10,000,000.00", "10000000.00", "-12.50"])
def test_parse_rejects_text_of_a_price_outside_the_range(text: str) -> None:
    with pytest.raises(ValueError, match="not a price"):
        parse_price(text)


@given(PRICES)
def test_I1_a_printed_price_reads_back_as_the_same_price(price: Decimal) -> None:
    assert parse_price(format_price(price)) == price

